public class CommonElements {

    public static void main(String[] args) {

        int[] a = {4, 9, 5, 1, 7};
        int[] b = {9, 4, 9, 8, 4};

        System.out.print("Common: ");

        for (int i = 0; i < a.length; i++) {

            // এই মানটি কি আগেই ছাপানো হয়ে গেছে?
            boolean printed = false;
            for (int k = 0; k < i; k++) {
                if (a[k] == a[i]) {
                    printed = true;
                }
            }
            if (printed) {
                continue;
            }

            // b-এর ভেতরে a[i] আছে কি না
            boolean found = false;
            for (int j = 0; j < b.length; j++) {
                if (a[i] == b[j]) {
                    found = true;
                }
            }

            if (found) {
                System.out.print(a[i] + " ");
            }
        }
    }
}

